#[test]
fn test_a_lattice_is_a_table_and_a_missing_rule_is_a_span() {
    let wd: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ln: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let et: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let pa: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let t: &mut String = &mut crate::port::new_text();
    tt_word(wd, ln, et, &crate::testport::text_blob("Intro")[..], 7200, 7000, 10200, 7800, 0);
    tt_grid(pa, 7200, 17200, 27200, 37200, 10000, 12000, 14000, 16000);
    tt_at(wd, ln, et, &crate::testport::text_blob("Item")[..], 7600, 10600, 1, 0);
    tt_at(wd, ln, et, &crate::testport::text_blob("Qty")[..], 17600, 10600, 1, 0);
    tt_at(wd, ln, et, &crate::testport::text_blob("Price")[..], 27600, 10600, 1, 0);
    tt_at(wd, ln, et, &crate::testport::text_blob("Bolt")[..], 7600, 12600, 0, 0);
    tt_at(wd, ln, et, &crate::testport::text_blob("10")[..], 17600, 12600, 0, 0);
    tt_at(wd, ln, et, &crate::testport::text_blob("2.50")[..], 27600, 12600, 0, 0);
    tt_at(wd, ln, et, &crate::testport::text_blob("Total")[..], 7600, 14600, 0, 0);
    tt_at(wd, ln, et, &crate::testport::text_blob("12.50")[..], 17600, 14600, 0, 0);
    tt_word(wd, ln, et, &crate::testport::text_blob("Outro")[..], 7200, 17200, 10200, 18000, 0);
    crate::testport::assert_eq(tt_run(wd, ln, et, pa, t), 0, "lattice: well formed");
    crate::testport::assert_text(t, "P[Intro];T3r;Gh;R;Ch[Item];Ch[Qty];Ch[Price];Gb;R;C[Bolt];C[10];C[2.50];R;C[Total];Cc2[12.50];P[Outro];", "a 3 x 3 lattice with its last row's two cells joined: header, body, and the paragraphs around it");
}
#[test]
fn test_columns_of_whitespace_are_a_table_and_prose_columns_are_not() {
    let wd: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let ln: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let et: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let pa: &mut crate::port::Cells = &mut crate::port::Cells::new();
    let t: &mut String = &mut crate::port::new_text();
    let t2: &mut String = &mut crate::port::new_text();
    // A header of bold words and four rows of a label and two numbers, right-aligned, no rule at all.
    tt_at(wd, ln, et, &crate::testport::text_blob("Fund")[..], 7200, 10000, 1, 0);
    tt_at(wd, ln, et, &crate::testport::text_blob("Q1")[..], 30000, 10000, 1, 1);
    tt_at(wd, ln, et, &crate::testport::text_blob("Q2")[..], 40000, 10000, 1, 1);
    tt_at(wd, ln, et, &crate::testport::text_blob("Alpha")[..], 7200, 11600, 0, 0);
    tt_at(wd, ln, et, &crate::testport::text_blob("3.0%")[..], 30000, 11600, 0, 1);
    tt_at(wd, ln, et, &crate::testport::text_blob("111.5%")[..], 40000, 11600, 0, 1);
    tt_at(wd, ln, et, &crate::testport::text_blob("Bo")[..], 7200, 13200, 0, 0);
    tt_at(wd, ln, et, &crate::testport::text_blob("4.7%")[..], 30000, 13200, 0, 1);
    tt_at(wd, ln, et, &crate::testport::text_blob("4.3%")[..], 40000, 13200, 0, 1);
    tt_at(wd, ln, et, &crate::testport::text_blob("Gammarays")[..], 7200, 14800, 0, 0);
    tt_at(wd, ln, et, &crate::testport::text_blob("12.1%")[..], 30000, 14800, 0, 1);
    tt_at(wd, ln, et, &crate::testport::text_blob("9.5%")[..], 40000, 14800, 0, 1);
    tt_at(wd, ln, et, &crate::testport::text_blob("Total")[..], 7200, 16400, 1, 0);
    tt_at(wd, ln, et, &crate::testport::text_blob("6.4%")[..], 30000, 16400, 1, 1);
    tt_at(wd, ln, et, &crate::testport::text_blob("6.6%")[..], 40000, 16400, 1, 1);
    crate::testport::assert_eq(tt_run(wd, ln, et, pa, t), 0, "whitespace: well formed");
    crate::testport::assert_text(t, "T3w;Gh;R;Chs[Fund];Che[Q1];Che[Q2];Gb;R;Cs[Alpha];C[3.0%];Ce[111.5%];R;Cs[Bo];C[4.7%];Ce[4.3%];R;Cs[Gammarays];C[12.1%];Ce[9.5%];Gf;R;Cws[Total];Cw[6.4%];Cwe[6.6%];", "a bold header, numeric columns right-aligned: header cells, body cells, alignment from the text extent");
    // Two columns of prose, four words a line: columns, not a table.
    crate::port::cells_drop(wd, 0);
    crate::port::cells_drop(ln, 0);
    crate::port::cells_drop(et, 0);
    tt_at(wd, ln, et, &crate::testport::text_blob("the old")[..], 7200, 10000, 0, 0);
    tt_at(wd, ln, et, &crate::testport::text_blob("was and")[..], 30000, 10000, 0, 0);
    tt_at(wd, ln, et, &crate::testport::text_blob("of the")[..], 7200, 11200, 0, 0);
    tt_at(wd, ln, et, &crate::testport::text_blob("that is")[..], 30000, 11200, 0, 0);
    tt_at(wd, ln, et, &crate::testport::text_blob("and then")[..], 7200, 12400, 0, 0);
    tt_at(wd, ln, et, &crate::testport::text_blob("went on")[..], 30000, 12400, 0, 0);
    tt_at(wd, ln, et, &crate::testport::text_blob("she said")[..], 7200, 13600, 0, 0);
    tt_at(wd, ln, et, &crate::testport::text_blob("to him")[..], 30000, 13600, 0, 0);
    crate::testport::assert_eq(tt_run(wd, ln, et, pa, t2), 0, "prose: well formed");
    crate::testport::assert_text(t2, "P[the old];P[was and];P[of the];P[that is];P[and then];P[went on];P[she said];P[to him];", "lowercase text with half the cells empty is not a table");
}
